import React from 'react';

function MovieList() {

    const movies = [
        {
        title: 'project hail mary',
        genre: 'sci-fi',
        releaseYear: '2026'
    },

    {
        title: 'one piece: film red',
        genre: 'anime',
        releaseYear: '2022'
    },

    {
        title: 'la la land',
        genre: 'musical',
        releaseYear: '2016'
    }
];

    return (
        <div>
            <h1>Movie List</h1>
            <div>
                {movies.map((movie) => (
                    <div>
                        <h2>{movie.title}</h2>
                        <p>{movie.genre}</p>
                        <p>{movie.releaseYear}</p>
                    </div>
                ))}
            </div>
        </div>
    );
}

export default MovieList;
